import sys
import csv
import json

filepath = r"D:\Anuj\Pearl-ASsignment\amazon-products.csv"
csv.field_size_limit(2147483647)

with open(filepath, "r", encoding="utf-8", newline="", errors="replace") as f:
    reader = csv.reader(f)
    header = next(reader)

    triple_quote_cols = {}
    literal_null_cols = {}
    empty_str_cols = {}
    json_parse_status = {col: {"valid": 0, "invalid": 0, "null_or_empty": 0} for col in [
        'categories', 'variations', 'delivery', 'features', 'buybox_prices', 
        'images', 'product_details', 'prices_breakdown'
    ]}

    row_idx = 0
    for row in reader:
        row_idx += 1
        for col_idx, cell in enumerate(row):
            col_name = header[col_idx]

            # Check triple quoting (starts and ends with literal double quote)
            if cell.startswith('"') and cell.endswith('"') and len(cell) >= 2:
                triple_quote_cols[col_name] = triple_quote_cols.get(col_name, 0) + 1

            # Check 'null' vs ''
            if cell == 'null':
                literal_null_cols[col_name] = literal_null_cols.get(col_name, 0) + 1
            elif cell == '':
                empty_str_cols[col_name] = empty_str_cols.get(col_name, 0) + 1

            # Check JSON columns
            if col_name in json_parse_status:
                if cell in ('null', '', 'None'):
                    json_parse_status[col_name]["null_or_empty"] += 1
                else:
                    try:
                        json.loads(cell)
                        json_parse_status[col_name]["valid"] += 1
                    except Exception as e:
                        json_parse_status[col_name]["invalid"] += 1

print("=== TRIPLE QUOTE / LITERAL QUOTES IN PARSED VALUES ===")
for col, cnt in sorted(triple_quote_cols.items(), key=lambda x: -x[1]):
    print(f"{col:25}: {cnt} rows")

print("\n=== LITERAL 'null' STRING IN CELLS ===")
for col, cnt in sorted(literal_null_cols.items(), key=lambda x: -x[1]):
    print(f"{col:25}: {cnt} rows")

print("\n=== EMPTY STRING '' IN CELLS ===")
for col, cnt in sorted(empty_str_cols.items(), key=lambda x: -x[1])[:15]:
    print(f"{col:25}: {cnt} rows")

print("\n=== JSON PARSING IN COMPLEX COLUMNS ===")
for col, stats in json_parse_status.items():
    print(f"{col:20}: valid={stats['valid']}, invalid={stats['invalid']}, null/empty={stats['null_or_empty']}")
